//go:build integration

// Integration tests for the repositories: they run against a real Postgres
// with the migrations generated by Ent/Atlas applied, proving what unit tests
// cannot reach: the ent-to-snapshot mapper, the aggregate upsert and the CHECK
// constraints generated from the schema. The `integration` build tag keeps
// them out of the everyday `go test ./...`; run them with
// `make test-integration`.
package entrepo_test

import (
	"context"
	"database/sql"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"

	"github.com/luigimenezes13/financial-manager/internal/financialtracking/adapter/entrepo"
	"github.com/luigimenezes13/financial-manager/internal/financialtracking/adapter/entrepo/ent"
	"github.com/luigimenezes13/financial-manager/internal/platform/db"
)

var (
	testDB     *sql.DB
	testClient *ent.Client
)

const migrationsDir = "../../../../migrations/financialtracking"

func TestMain(main *testing.M) {
	databaseURL := os.Getenv("TEST_DATABASE_URL")
	if databaseURL == "" {
		fmt.Println("TEST_DATABASE_URL is empty, use `make test-integration`")
		os.Exit(1)
	}

	ctx := context.Background()
	database, err := db.NewSQLDB(ctx, databaseURL)
	if err != nil {
		fmt.Printf("failed to connect to the test Postgres: %v\n", err)
		os.Exit(1)
	}
	testDB = database
	testClient = entrepo.NewClient(database)

	if err := resetSchema(ctx, database); err != nil {
		fmt.Printf("failed to reset the schema: %v\n", err)
		os.Exit(1)
	}
	if err := applyMigrations(ctx, database); err != nil {
		fmt.Printf("failed to apply migrations: %v\n", err)
		os.Exit(1)
	}

	code := main.Run()
	_ = testClient.Close()
	os.Exit(code)
}

// resetSchema drops ONLY the tables owned by this bounded context. The test
// database is shared and `go test` runs packages in parallel, so a broad
// `DROP SCHEMA public CASCADE` would wipe the Identity tables in the middle of
// its tests. Atlas migrations are forward-only, so this drop is the test
// environment's "down": safe here, catastrophic in production, which is why it
// lives behind a test build tag.
func resetSchema(ctx context.Context, database *sql.DB) error {
	_, err := database.ExecContext(ctx,
		`DROP TABLE IF EXISTS transactions, category_rules, categories, accounts CASCADE`)
	return err
}

// applyMigrations runs the versioned .sql files in order. In production Atlas
// applies them (tracking history and checking atlas.sum); here the goal is
// only the real schema without depending on the installed binary. Atlas file
// names start with a timestamp, so lexicographic order is chronological order.
func applyMigrations(ctx context.Context, database *sql.DB) error {
	entries, err := os.ReadDir(migrationsDir)
	if err != nil {
		return fmt.Errorf("reading migrations: %w", err)
	}

	files := sqlFileNames(entries)
	sort.Strings(files)

	for _, file := range files {
		statements, err := os.ReadFile(filepath.Join(migrationsDir, file))
		if err != nil {
			return fmt.Errorf("reading %s: %w", file, err)
		}
		if _, err := database.ExecContext(ctx, string(statements)); err != nil {
			return fmt.Errorf("executing %s: %w", file, err)
		}
	}

	return nil
}

func sqlFileNames(entries []os.DirEntry) []string {
	files := make([]string, 0, len(entries))
	for _, entry := range entries {
		if strings.HasSuffix(entry.Name(), ".sql") {
			files = append(files, entry.Name())
		}
	}
	return files
}

// truncateAll empties the tables before each test. These tests deliberately
// do NOT use t.Parallel(): they share one database, and running them in
// parallel would let one test truncate another's rows.
func truncateAll(t *testing.T) {
	t.Helper()

	_, err := testDB.ExecContext(context.Background(),
		`TRUNCATE transactions, category_rules, categories, accounts`)
	if err != nil {
		t.Fatalf("failed to truncate tables: %v", err)
	}
}
